using System.Text;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;namespace AssetForge.Web.Pages;public class ReportsModel(AssetForgeDbContext db):PageModel{public int WarrantyDue{get;set;}public decimal AssetValue{get;set;}public decimal RepairCost{get;set;}public async Task OnGetAsync(){await Phase4Upgrade.ApplyAsync(db);var today=DateOnly.FromDateTime(DateTime.Today);WarrantyDue=await db.Assets.CountAsync(x=>x.WarrantyExpires>=today&&x.WarrantyExpires<=today.AddDays(30));AssetValue=await db.Assets.SumAsync(x=>x.PurchasePrice??0);RepairCost=await db.MaintenanceRecords.SumAsync(x=>x.Cost??0);}public async Task<IActionResult> OnGetExportAsync(){var rows=await db.Assets.Include(x=>x.Category).Include(x=>x.Location).ToListAsync();var b=new StringBuilder("AssetTag,Name,Category,Status,Location,SerialNumber,PurchasePrice,WarrantyExpires\r\n");foreach(var a in rows)b.AppendLine(string.Join(',',new[]{a.AssetTag,a.Name,a.Category?.Name,a.Status,a.Location?.Name,a.SerialNumber,a.PurchasePrice?.ToString("0.00"),a.WarrantyExpires?.ToString("yyyy-MM-dd")}.Select(Csv)));return File(Encoding.UTF8.GetBytes(b.ToString()),"text/csv","assetforge-export.csv");}private static string Csv(string? v)=>$"\"{(v??"").Replace("\"","\"\"")}\"";}
